TEST_F(TADDTest, case_bf16_16x256_16x256_16x256) { test_tadd<bfloat16_t, 16, 256, 16, 256>(); }
#endif

#!/usr/bin/env python3
# coding=utf-8
# --------------------------------------------------------------------------------
# Copyright (c) 2025 Huawei Technologies Co., Ltd.
